1	package contractsentinel
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件围绕比较功能的一项业务回归口径：同一规则标识在基准报告中为
11	// “发现缺陷”、在新报告中为“通过”时，只有两侧规则的完整定义——版本、检查
12	// 种类、严重级别、引用的不变式、requiresABI 是否需要 ABI——完全一致，才能
13	// 把它记为“已消除缺陷”。只改动其中一项定义时必须记为“规则变化”：用户看到
14	// 缺陷总数下降，需要分清是同一检查标准下的缺陷消除，还是检查标准本身已经
15	// 变化。版本字符串相同不能替代完整定义的一致性。
16	//
17	// 所有用例都走 BuildReport -> SaveReport -> DiffStore 的正常归档与读回路径，
18	// 比较的是同一产物（同一名称、同一内容哈希）的两份合法报告；产物自带 ABI 与
19	// 字节码，使 requiresABI 的规则和 symbolic 规则的报告都能正常保存和读回。
20	
21	// ruleChangeEvidence 刻意包含中文、换行与前后空白；定义变化不得改写旧证据。
22	const ruleChangeEvidence = "  旧反例：调用顺序如下\n  attacker.withdraw() 再入  "
23	
24	// ruleChangeBaseRule 是基准侧规则定义；每个漂移用例只改其中一个字段。
25	func ruleChangeBaseRule() Rule {
26		return Rule{
27			ID:          "reentrancy-guard",
28			Kind:        "static",
29			Severity:    "high",
30			Invariant:   "no-reentrant-withdraw",
31			RequiresABI: false,
32			Version:     "3.1.0",
33		}
34	}
35	
36	// saveRuleChangeCheckReport 通过外部检查记录落盘一份单规则报告：基准侧保留
37	// 具体反例，新侧记录通过。证据中的中文、换行和前后空白随检查说明原样归档。
38	func saveRuleChangeCheckReport(t *testing.T, dir string, artifact Artifact, rule Rule, status string, note string) Report {
39		t.Helper()
40		report := saveCheckReport(t, dir, artifact, []Rule{rule}, []CheckRecord{{
41			ArtifactHash: ArtifactHash(artifact),
42			RuleID:       rule.ID,
43			Version:      rule.Version,
44			Status:       status,
45			Note:         note,
46		}})
47		return report
48	}
49	
50	// assertRuleFields 比较归档读回的完整规则定义与期望定义。
51	func assertRuleFields(t *testing.T, where string, got ReportRule, want Rule, status, note string) {
52		t.Helper()
53		if got.ID != want.ID || got.Kind != want.Kind || got.Severity != want.Severity ||
54			got.Invariant != want.Invariant || got.RequiresABI != want.RequiresABI ||
55			got.Version != want.Version {
56			t.Errorf("%s definition = {id:%q kind:%q severity:%q invariant:%q requiresABI:%v version:%q}, want {id:%q kind:%q severity:%q invariant:%q requiresABI:%v version:%q}",
57				where, got.ID, got.Kind, got.Severity, got.Invariant, got.RequiresABI, got.Version,
58				want.ID, want.Kind, want.Severity, want.Invariant, want.RequiresABI, want.Version)
59		}
60		if got.Status != status {
61			t.Errorf("%s status = %q, want %q", where, got.Status, status)
62		}
63		if got.Note != note {
64			t.Errorf("%s note = %q, want %q", where, got.Note, note)
65		}
66	}
67	
68	// TestDiffDefectToPassWithSingleDefinitionDriftIsRuleChange 逐项覆盖五个定义
69	// 字段：每个用例只改其中一项，其余定义保持相同。四种用例刻意保持版本字符串
70	// 不变——版本相同不代表定义一致。
71	func TestDiffDefectToPassWithSingleDefinitionDriftIsRuleChange(t *testing.T) {
72		cases := []struct {
73			name  string
74			drift func(Rule) Rule
75		}{
76			{"version only", func(r Rule) Rule {
77				r.Version = "3.2.0"
78				return r
79			}},
80			{"kind only, version unchanged", func(r Rule) Rule {
81				r.Kind = "symbolic"
82				return r
83			}},
84			{"severity only, version unchanged", func(r Rule) Rule {
85				r.Severity = "critical"
86				return r
87			}},
88			{"invariant only, version unchanged", func(r Rule) Rule {
89				r.Invariant = "no-reentrant-withdraw-v2"
90				return r
91			}},
92			{"requiresABI only, version unchanged", func(r Rule) Rule {
93				r.RequiresABI = true
94				return r
95			}},
96		}
97		for _, tc := range cases {
98			t.Run(tc.name, func(t *testing.T) {
99				dir := t.TempDir()
100				// 产物自带 ABI 与字节码：requiresABI 的新侧规则与 symbolic 检查种类
101				// 都满足输入要求，两份报告可以正常保存和读回。
102				artifact := sampleArtifact()
103				hash := ArtifactHash(artifact)
104	
105				beforeRule := ruleChangeBaseRule()
106				afterRule := tc.drift(ruleChangeBaseRule())
107				before := saveRuleChangeCheckReport(t, dir, artifact, beforeRule, StatusDefect, ruleChangeEvidence)
108				after := saveRuleChangeCheckReport(t, dir, artifact, afterRule, StatusPass, "")
109	
110				// 两份报告必须能从归档独立读回，且基准侧仍带着原有产物哈希、规则
111				// 标识、版本及反例证据，新侧没有缺陷记录。
112				loadedBefore, err := LoadReport(dir, before.ReportID)
113				if err != nil {
114					t.Fatalf("load before: %v", err)
115				}
116				loadedAfter, err := LoadReport(dir, after.ReportID)
117				if err != nil {
118					t.Fatalf("load after: %v", err)
119				}
120				if len(loadedBefore.Findings) != 1 || len(loadedAfter.Findings) != 0 {
121					t.Fatalf("archived findings = %d/%d, want 1/0", len(loadedBefore.Findings), len(loadedAfter.Findings))
122				}
123	
124				diff, err := DiffStore(dir, before.ReportID, after.ReportID)
125				if err != nil {
126					t.Fatalf("diff must succeed for a definition drift: %v", err)
127				}
128	
129				// 比较方向与报告标识按归档选择保留。
130				if diff.Before.ReportID != before.ReportID || diff.After.ReportID != after.ReportID {
131					t.Errorf("refs = %q/%q, want %q/%q", diff.Before.ReportID, diff.After.ReportID, before.ReportID, after.ReportID)
132				}
133				if diff.ArtifactHashChanged || diff.ArtifactNameChanged {
134					t.Error("same artifact must not be flagged changed")
135				}
136	
137				// 恰好一条“规则变化”，不能记成已消除缺陷。
138				if len(diff.Results) != 1 {
139					t.Fatalf("results = %d, want 1: %+v", len(diff.Results), diff.Results)
140				}
141				entry := diff.Results[0]
142				if entry.RuleID != beforeRule.ID {
143					t.Errorf("rule id = %q, want %q", entry.RuleID, beforeRule.ID)
144				}
145				if entry.Change != ChangeRuleChanged {
146					t.Fatalf("change = %q, want %q", entry.Change, ChangeRuleChanged)
147				}
148	
149				// 计数：规则变化为一；已消除缺陷、新发现缺陷、检查状态变化（及其余
150				// 类别）均为零。
151				s := diff.Summary
152				if s.ChangedRules != 1 {
153					t.Errorf("changedRules = %d, want 1", s.ChangedRules)
154				}
155				if s.ResolvedDefects != 0 || s.NewDefects != 0 || s.StatusChanges != 0 ||
156					s.NoteChanges != 0 || s.NoChange != 0 || s.AddedRules != 0 || s.RemovedRules != 0 {
157					t.Errorf("every non-rule-change count must be zero: %+v", s)
158				}
159				// 两个缺陷总数反映各自报告里的实际发现，不代表已消除缺陷的数量。
160				if s.BeforeDefects != 1 || s.AfterDefects != 0 {
161					t.Errorf("defect totals = %d/%d, want 1/0 (actual findings, not resolved count)",
162						s.BeforeDefects, s.AfterDefects)
163				}
164	
165				// 两侧完整规则、原始状态和说明都保留。
166				if entry.Before == nil || entry.After == nil {
167					t.Fatal("both sides must be present for 规则变化")
168				}
169				assertRuleFields(t, "before side", entry.Before.Rule, beforeRule, StatusDefect, ruleChangeEvidence)
170				assertRuleFields(t, "after side", entry.After.Rule, afterRule, StatusPass, "")
171	
172				// 基准侧缺陷仍带着原有产物哈希、规则标识、版本及反例证据；定义变化
173				// 不能改写旧证据，也不能把旧版本换成新版本。
174				finding := entry.Before.Finding
175				if finding == nil {
176					t.Fatal("baseline defect must keep its finding")
177				}
178				if finding.ArtifactHash != hash {
179					t.Errorf("finding artifact hash = %q, want %q", finding.ArtifactHash, hash)
180				}
181				if finding.RuleID != beforeRule.ID {
182					t.Errorf("finding rule id = %q, want %q", finding.RuleID, beforeRule.ID)
183				}
184				if finding.Version != beforeRule.Version {
185					t.Errorf("finding version = %q, want baseline %q (must not be rewritten to the new version)",
186						finding.Version, beforeRule.Version)
187				}
188				if finding.Severity != beforeRule.Severity {
189					t.Errorf("finding severity = %q, want baseline %q", finding.Severity, beforeRule.Severity)
190				}
191				if finding.Invariant != beforeRule.Invariant {
192					t.Errorf("finding invariant = %q, want baseline %q", finding.Invariant, beforeRule.Invariant)
193				}
194				if finding.Evidence != ruleChangeEvidence {
195					t.Errorf("finding evidence = %q, want %q verbatim", finding.Evidence, ruleChangeEvidence)
196				}
197				if entry.After.Finding != nil {
198					t.Errorf("passing side must carry no finding: %+v", entry.After.Finding)
199				}
200	
201				// 归档字节层面：证据中的中文、换行（JSON 中转义为 \n）和前后空白
202				// 必须原样落盘，不能被修剪或替换。
203				data, err := os.ReadFile(filepath.Join(dir, before.ReportID+".json"))
204				if err != nil {
205					t.Fatal(err)
206				}
207				wantEscaped := `"evidence":"  旧反例：调用顺序如下\n  attacker.withdraw() 再入  "`
208				if !strings.Contains(string(data), wantEscaped) {
209					t.Errorf("baseline archive must keep the raw evidence verbatim:\n%s", string(data))
210				}
211			})
212		}
213	}
214	
215	// TestDiffDefectToPassIdenticalDefinitionIsResolved 是定义全部一致的对照：
216	// 相同的“发现缺陷”到“通过”变化应归为“已消除缺陷”，而不是“规则变化”。
217	func TestDiffDefectToPassIdenticalDefinitionIsResolved(t *testing.T) {
218		dir := t.TempDir()
219		artifact := sampleArtifact()
220		hash := ArtifactHash(artifact)
221	
222		rule := ruleChangeBaseRule()
223		before := saveRuleChangeCheckReport(t, dir, artifact, rule, StatusDefect, ruleChangeEvidence)
224		after := saveRuleChangeCheckReport(t, dir, artifact, rule, StatusPass, "")
225	
226		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
227		if err != nil {
228			t.Fatal(err)
229		}
230		if len(diff.Results) != 1 {
231			t.Fatalf("results = %d, want 1", len(diff.Results))
232		}
233		entry := diff.Results[0]
234		if entry.Change != ChangeResolvedDefect {
235			t.Fatalf("change = %q, want %q", entry.Change, ChangeResolvedDefect)
236		}
237		s := diff.Summary
238		if s.ResolvedDefects != 1 {
239			t.Errorf("resolvedDefects = %d, want 1", s.ResolvedDefects)
240		}
241		if s.ChangedRules != 0 {
242			t.Errorf("changedRules = %d, want 0", s.ChangedRules)
243		}
244		if s.NewDefects != 0 || s.StatusChanges != 0 || s.NoteChanges != 0 || s.NoChange != 0 {
245			t.Errorf("unexpected counts: %+v", s)
246		}
247		// 同样的真实发现总数：一和零；对照用例与漂移用例在这里结果一致，区别只在
248		// 分类（已消除缺陷 vs 规则变化）。
249		if s.BeforeDefects != 1 || s.AfterDefects != 0 {
250			t.Errorf("defect totals = %d/%d, want 1/0", s.BeforeDefects, s.AfterDefects)
251		}
252		if entry.Before == nil || entry.After == nil {
253			t.Fatal("both sides must be present")
254		}
255		assertRuleFields(t, "before side", entry.Before.Rule, rule, StatusDefect, ruleChangeEvidence)
256		assertRuleFields(t, "after side", entry.After.Rule, rule, StatusPass, "")
257		if entry.Before.Finding == nil || entry.Before.Finding.ArtifactHash != hash ||
258			entry.Before.Finding.RuleID != rule.ID || entry.Before.Finding.Version != rule.Version ||
259			entry.Before.Finding.Evidence != ruleChangeEvidence {
260			t.Errorf("baseline finding must be preserved: %+v", entry.Before.Finding)
261		}
262		if entry.After.Finding != nil {
263			t.Errorf("passing side must carry no finding: %+v", entry.After.Finding)
264		}
265	}
266	
267	// TestDiffRuleChangeIsNotCountedAsResolved 把一个漂移场景与对照场景放在同一
268	// 份输出的相邻规则上，回归保障必须能区分用户实际得到的两类比较结果：标准未
269	// 变下的缺陷消除，与标准已变的规则变化。
270	func TestDiffRuleChangeIsNotCountedAsResolved(t *testing.T) {
271		dir := t.TempDir()
272		artifact := sampleArtifact()
273		hash := ArtifactHash(artifact)
274	
275		// 第一条：定义漂移（版本字符串不变，严重级别改变）+ 发现缺陷 -> 通过。
276		driftedBefore := ruleChangeBaseRule()
277		driftedAfter := ruleChangeBaseRule()
278		driftedAfter.Severity = "critical"
279		// 第二条：定义完全一致 + 发现缺陷 -> 通过。
280		sameRule := ruleChangeBaseRule()
281		sameRule.ID = "access-control"
282		sameRule.Severity = "medium"
283		sameRule.Invariant = "owner-only-withdraw"
284		sameRule.Version = "4.0.0"
285	
286		before := saveCheckReport(t, dir, artifact, []Rule{driftedBefore, sameRule}, []CheckRecord{
287			{ArtifactHash: hash, RuleID: driftedBefore.ID, Version: driftedBefore.Version, Status: StatusDefect, Note: ruleChangeEvidence},
288			{ArtifactHash: hash, RuleID: sameRule.ID, Version: sameRule.Version, Status: StatusDefect, Note: " 旧缺陷二 "},
289		})
290		after := saveCheckReport(t, dir, artifact, []Rule{driftedAfter, sameRule}, []CheckRecord{
291			{ArtifactHash: hash, RuleID: driftedAfter.ID, Version: driftedAfter.Version, Status: StatusPass},
292			{ArtifactHash: hash, RuleID: sameRule.ID, Version: sameRule.Version, Status: StatusPass},
293		})
294	
295		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
296		if err != nil {
297			t.Fatal(err)
298		}
299		changeByID := map[string]string{}
300		for _, r := range diff.Results {
301			changeByID[r.RuleID] = r.Change
302		}
303		if changeByID[driftedBefore.ID] != ChangeRuleChanged {
304			t.Errorf("drifted rule = %q, want %q", changeByID[driftedBefore.ID], ChangeRuleChanged)
305		}
306		if changeByID[sameRule.ID] != ChangeResolvedDefect {
307			t.Errorf("identical rule = %q, want %q", changeByID[sameRule.ID], ChangeResolvedDefect)
308		}
309		s := diff.Summary
310		if s.ChangedRules != 1 || s.ResolvedDefects != 1 {
311			t.Errorf("summary = %+v, want one rule change and one resolved defect", s)
312		}
313		if s.BeforeDefects != 2 || s.AfterDefects != 0 {
314			t.Errorf("defect totals = %d/%d, want 2/0", s.BeforeDefects, s.AfterDefects)
315		}
316	}
