	}
	if entry.Before.Finding.ArtifactHash != ArtifactHash(artifact) {
		t.Errorf("evidence artifact hash = %q", entry.Before.Finding.ArtifactHash)
	}
	if entry.Before.Finding.Version != "1.0.0" {
