45		}
46		byRule := map[string]Finding{}
47		for _, f := range findings {
48			byRule[f.Rule] = f
49		}
50		for _, want := range []struct {
51			rule, severity, invariant string
52		}{
53			{"r1", "high", "inv-a"},
54			{"r2", "medium", "inv-b"},
55			{"r3", "low", "inv-c"},
56		} {
57			f, ok := byRule[want.rule]
58			if !ok {
