278	// 即使同次输入中排在前面的规则已能确认缺陷，输入不足也必须整次审计失败：
279	// 不能返回那部分发现。
280	func TestRunMissingContentFailsWholeAuditWithoutPartialFindings(t *testing.T) {
281		rules := []Rule{
