27			{ID: "b-tool-to-pass", Kind: "static", Severity: "medium", Invariant: "inv-tool", RequiresABI: true, Version: "2"},
28			{ID: "c-unchecked-to-pass", Kind: "static", Severity: "info", Invariant: "inv-unchecked", Version: "3"},
