71	// auditDiffReport 用给定规则与检查记录通过真实 audit 命令落盘一份报告并解码返回。
72	func auditDiffReport(t *testing.T, bin, work, store, name string, artifact cliWireArtifact, rules []cliWireRule, checks []cliWireCheck) contractsentinel.Report {
73		t.Helper()
74		in := cliWireInput{Artifact: artifact, Rules: rules, Checks: checks}
75		input := writeStructInput(t, work, name, in)
76		stdout, stderr, code := runCLIAudit(t, bin, input, store)
77		if code != 0 {
78			t.Fatalf("setup audit %s must succeed, exit=%d stderr=%s", name, code, stderr)
79		}
80		return decodeReport(t, stdout)
81	}
