102		t.Helper()
103		var d contractsentinel.DiffResult
104		if err := json.Unmarshal([]byte(raw), &d); err != nil {
105			t.Fatalf("diff output is not parseable JSON: %v\n%s", err, raw)
106		}
107		return d
108	}
